update public.evaluations set research_status = 'reviewed', candidate_status = 'neutral', fit_grade = 'B+', fit_score = 4.1, confidence = 'high', positives = array['Only about five miles from Los Alamitos, making repeat visits practical.', 'Fresh WPN/EventLink now confirms broad current Magic coverage: Thursday Commander, Saturday Commanderfest, Sunday casual play from prior store source, Wednesday draft, Modern, Pauper, cEDH, Standard Showdown, Commander Party branding, and multiple prerelease weekends.', 'User field notes still give unusually valuable lived texture: Saturday has structured random pods/loose rounds, while Sunday has had a more freeform casual vibe.', 'WPN Premium status, active official/source stack, and current WPN event breadth make Finch one of the strongest known planning candidates.']::text[], cautions = array['Birdcage and cEDH-forward promotion are meaningful store-character signals but are not the default casual fit.', 'Sunday casual play remains useful but still needs better Commander-density and best-arrival-window texture.', 'Saturday Commanderfest may be structured enough to feel different from relaxed open play.', 'Discord was previously inspected and rated low-usefulness for current Commander intelligence, so pre-arrival coordination still relies more on site/social/user observation than active public LFG evidence.']::text[], open_questions = array['How Commander-heavy is Sunday Finch and Sparrow Casual Play in current practice?', 'What is the best Sunday casual/open-play arrival window?', 'What is the current Thursday Commander table texture, bracket mix, and proxy expectation?']::text[] where entity_type is not distinct from 'venue' and entity_id is not distinct from 'finch-sparrow';
-- Reason: Add a structured Places evaluation for The Guild House after fresh WPN event breadth strengthens the visit case while preserving texture unknowns.
insert into public.evaluations (entity_type, entity_id, research_status, candidate_status, fit_grade, fit_score, confidence, positives, cautions, open_questions) values ('venue', 'guild-house', 'reviewed', 'neutral', 'B+', 4.0, 'high', array['Nearby Bellflower location is practical for repeat visits from Los Alamitos.', 'Fresh WPN/EventLink broadens the planning read beyond Tuesday Commander: Friday draft, Standard Showdown, Saturday Commander League / 2HG Commander League, and Hobbit prerelease are all currently visible.', 'Prior social/calendar evidence supports an active store-controlled event ecosystem, not just a locator listing.', 'Prior Discord baseline supports reservations and arranged-group logistics.']::text[], array['Fresh WPN org reports the store as WPN but not WPN Premium, so the app should not present a current Premium badge without another source.', 'Discord/reservation evidence helps groups secure space but does not yet prove public solo-arrival pod matching.', 'Proxy policy and casual power-level norms remain unstated in the currently accepted source stack.']::text[], array['Can an unaffiliated solo player reliably find a Commander pod on Tuesday or Saturday?', 'What are the proxy and power-level norms for routine Commander and Commander League?', 'Does the Discord/table-reservation workflow help individual players or mostly prearranged groups?']::text[]);
-- Reason: Create a complete-enough Places read for Guildhall as a niche venue-first Commander option rather than a broad store candidate.
insert into public.evaluations (entity_type, entity_id, research_status, candidate_status, fit_grade, fit_score, confidence, positives, cautions, open_questions) values ('venue', 'guildhall-whittier', 'reviewed', 'neutral', 'C+', 3.2, 'medium', array['Fresh WPN/EventLink confirms current Tuesday Casual Commander at 5:30 PM.', 'Event copy explicitly says players can bring friends or meet others looking for a game, which is a useful solo-arrival signal.', 'Bar/venue setting may be socially easier than a tournament-forward store for a casual experiment.']::text[], array['Guildhall is venue-first rather than store-first, with no current WPN evidence for draft, prerelease, FNM, or broader Magic programming.', 'Food/drink spend is tied to booster eligibility and no outside food/drink is allowed.', 'Actual Commander turnout, proxy norms, and table texture remain unverified.']::text[], array['How many Commander players show up on a normal Tuesday?', 'Is the bar atmosphere compatible with focused Commander games?', 'What proxy and power-level norms are expected?']::text[]);
-- Reason: Promote Alakazam from thin lead to complete-enough lower-priority planning candidate after current WPN event reconciliation.
insert into public.evaluations (entity_type, entity_id, research_status, candidate_status, fit_grade, fit_score, confidence, positives, cautions, open_questions) values ('venue', 'alakazam-comics', 'reviewed', 'neutral', 'B-', 3.4, 'medium', array['Fresh WPN/EventLink confirms multiple current Magic rows: Marvel Super-Heroes draft tables, Commander Draft, Pauper FNM, and Commander Party.', 'Existing Alakazam Comics MTG Facebook and prior source stack support a real Magic-specific identity rather than a token comic-store listing.', 'Small table capacities may make events more structured and knowable if they fire.']::text[], array['Irvine distance and small-capacity table structure make it less obvious as a repeat home-base candidate.', 'Existing Commander Draft row was overprojected and should be treated as finite unless refreshed.', 'Current solo-arrival texture, review texture, and event firing reliability remain unresolved.']::text[], array['Do small-cap Alakazam FNM table events reliably fire?', 'Is Facebook still the primary current Magic communication route?', 'What is the Commander Draft / Commander Party crowd and proxy-power texture?']::text[]);
-- Reason: Finch prerelease visibility is attention-worthy because it changes a prior open question for a close high-confidence target.
insert into public.signals (id, category, priority, status, source_id, captured_at, observed_at, expires_at, related_entity_type, related_entity_id, summary, details, evidence_url, confidence, suggested_action, promotion_target, dedupe_key) values ('signal-finch-prerelease-weekends-visible-2026-07-23', 'event_opportunity', 'normal', 'new', 'src-wpn-6718', '2026-07-23T18:30:00-07:00', '2026-07-23T17:07:36-07:00', '2026-08-10T00:00:00-07:00', 'venue', 'finch-sparrow', 'Finch now has WPN-visible Hobbit prerelease sessions across August 7-9.', 'Fresh Wizards/EventLink shows six Finch Hobbit prerelease sealed sessions and later Reality Fracture prerelease sessions. Because Finch is close and already high-confidence, this is useful planning intelligence beyond routine weekly rows.', 'https://locator.wizards.com/store/6718', 'high', 'If prerelease/sealed is appealing, compare Finch''s August 7-9 times against other close stores before the weekend fills up.', 'event_proposal', 'finch-sparrow:wpn:hobbit-prerelease-visible:2026-07-23');
-- Reason: The Guild House event breadth materially changes the planning read and is sparse enough for Signals.
insert into public.signals (id, category, priority, status, source_id, captured_at, observed_at, expires_at, related_entity_type, related_entity_id, summary, details, evidence_url, confidence, suggested_action, promotion_target, dedupe_key) values ('signal-guild-house-weekend-magic-breadth-2026-07-23', 'event_opportunity', 'normal', 'new', 'src-wpn-7516', '2026-07-23T18:30:00-07:00', '2026-07-23T17:07:36-07:00', '2026-08-09T00:00:00-07:00', 'venue', 'guild-house', 'The Guild House has newly visible weekend Commander League and Hobbit prerelease opportunities.', 'Fresh Wizards/EventLink expands The Guild House beyond the existing Tuesday Commander row: July 25 Commander League, August 1 2HG Commander League, Friday draft, Standard Showdown, and August 7-8 Hobbit prerelease are visible. The source also reports the store as WPN but not current WPN Premium.', 'https://locator.wizards.com/store/7516', 'high', 'Consider The Guild House as a near-term nearby try-soon candidate, especially for Saturday Commander League or Hobbit prerelease; check solo-arrival/proxy texture before relying on it as a home-base lane.', 'event_proposal', 'guild-house:wpn:weekend-magic-breadth:2026-07-23');
-- Reason: Create pending Updates/research-change marker for this reviewable batch.
insert into public.research_changes (id, detected_at, change_type, entity_type, entity_id, summary, review_status) values ('change-finch-guildhouse-guildhall-alakazam-main-pass-2026-07-23', '2026-07-23T18:30:00-07:00', 'research_update', 'venue', 'finch-sparrow', 'Proposed mixed main-pass refinement for Finch, The Guild House, Guildhall, and Alakazam: add missing WPN prerelease/draft/Commander League/FNM rows, correct Alakazam overprojection, refresh Places evaluations, and surface two sparse planning Signals.', 'proposed');

